def get_pairs(word):
    return set(zip(word[:-1],word[1:]))
def bpe(tok):
    word=tuple(tok); pairs=get_pairs(word)
    if not pairs: return [tok]
    while True:
        bigram=min(pairs,key=lambda p:bpe_ranks.get(p,1e18))
        if bigram not in bpe_ranks: break
        a,b=bigram; new=[]; i=0
